document.getElementById("nav").innerHTML=Object.keys(C).map(x=>`<a href="#${x}" class="${x==k?"on":""}">${C[x][1]}</a>`).join("");
document.title=(k=="home"?"":C[k][1]+" · ")+"NotAraxx Technologies";scrollTo(0,0);
